import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <cmath>
#include <algorithm>

using namespace cute;

// ---------------------------------------------------------------------
// Kernel A: partial reduction of sum and sum-of-squares per batch row n
// ---------------------------------------------------------------------
__global__ void reduce_kernel(
    const float* __restrict__ X,
    int N, int M,
    double* __restrict__ sum,
    double* __restrict__ sumsq)
{
  int n = blockIdx.x;
  int tid    = threadIdx.x;
  int stride = blockDim.x * gridDim.y;
  int start  = blockIdx.y * blockDim.x + tid;
  double s = 0.0, sq = 0.0;
  if ((M & 3) == 0) {
    const float4* X4 = reinterpret_cast<const float4*>(X + (int64_t)n * (int64_t)M);
    int M4 = M >> 2;
    for (int m = start; m < M4; m += stride) {
      float4 v4 = X4[m];
      s  += (double)v4.x + (double)v4.y + (double)v4.z + (double)v4.w;
      sq += (double)v4.x * (double)v4.x + (double)v4.y * (double)v4.y +
            (double)v4.z * (double)v4.z + (double)v4.w * (double)v4.w;
    }
  } else {
    // View this row as a 1D CuTe tensor of length M
    Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * (int64_t)M),
                             make_shape(M), make_stride(Int<1>{}));
    for (int m = start; m < M; m += stride) {
      float v = mX(m);
      s  += (double)v;
      sq += (double)v * (double)v;
    }
  }
  // Warp-level reduction using shuffle instructions to reduce shared
  // memory traffic and synchronization overhead.
  const unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    s  += __shfl_down_sync(mask, s, offset);
    sq += __shfl_down_sync(mask, sq, offset);
  }
  int lane   = tid & 31;
  int warpId = tid >> 5;
  extern __shared__ double smem[];
  double* ssum = smem;
  double* ssq  = smem + (blockDim.x >> 5);
  if (lane == 0) {
    ssum[warpId] = s;
    ssq[warpId]  = sq;
  }
  __syncthreads();
  int numWarps = blockDim.x >> 5;
  if (warpId == 0) {
    double s2  = (lane < numWarps) ? ssum[lane] : 0.0;
    double sq2 = (lane < numWarps) ? ssq[lane]  : 0.0;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      s2  += __shfl_down_sync(mask, s2, offset);
      sq2 += __shfl_down_sync(mask, sq2, offset);
    }
    if (lane == 0) {
      atomicAdd(&sum[n], s2);
      atomicAdd(&sumsq[n], sq2);
    }
  }
}

// ---------------------------------------------------------------------
// Kernel B: finalize mean and inverse-std per row
// ---------------------------------------------------------------------
__global__ void finalize_kernel(
    const double* __restrict__ sum,
    const double* __restrict__ sumsq,
    double* __restrict__ mean,
    double* __restrict__ invstd,
    int N, int M, float eps)
{
  int n = blockIdx.x * blockDim.x + threadIdx.x;
  if (n < N) {
    double m   = sum[n] / (double)M;
    double var = sumsq[n] / (double)M - m * m;
    if (var < 0.0) var = 0.0;
    mean[n]   = m;
    invstd[n] = 1.0 / sqrt(var + (double)eps);
  }
}

// ---------------------------------------------------------------------
// Kernel C: elementwise normalization + affine transform
// ---------------------------------------------------------------------
__global__ void normalize_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    const double* __restrict__ mean,
    const double* __restrict__ invstd,
    float* __restrict__ Y,
    int N, int M)
{
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.x * blockDim.x;
  if ((M & 3) == 0) {
    int M4 = M >> 2;
    const float4* X4 = reinterpret_cast<const float4*>(X);
    const float4* W4 = reinterpret_cast<const float4*>(W);
    const float4* B4 = reinterpret_cast<const float4*>(B);
    float4* Y4 = reinterpret_cast<float4*>(Y);
    // Loop over columns in the outer loop so weight/bias (which only
    // depend on the column index) are read once from global memory
    // and reused across all N rows via registers, cutting redundant
    // global loads of W/B by a factor of N.
    for (int64_t m4 = idx; m4 < (int64_t)M4; m4 += stride) {
      float4 w = W4[m4];
      float4 b = B4[m4];
      for (int n = 0; n < N; ++n) {
        float4 x = X4[(int64_t)n * M4 + m4];
        double mn = mean[n];
        double is = invstd[n];
        float4 y;
        y.x = (float)(((double)x.x - mn) * is) * w.x + b.x;
        y.y = (float)(((double)x.y - mn) * is) * w.y + b.y;
        y.z = (float)(((double)x.z - mn) * is) * w.z + b.z;
        y.w = (float)(((double)x.w - mn) * is) * w.w + b.w;
        Y4[(int64_t)n * M4 + m4] = y;
      }
    }
  } else {
    Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N, M), make_stride(M, Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N, M), make_stride(M, Int<1>{}));
    Tensor vW = make_tensor(make_gmem_ptr(W), make_shape(M), make_stride(Int<1>{}));
    Tensor vB = make_tensor(make_gmem_ptr(B), make_shape(M), make_stride(Int<1>{}));
    for (int64_t m = idx; m < (int64_t)M; m += stride) {
      float w = vW((int)m);
      float b = vB((int)m);
      for (int n = 0; n < N; ++n) {
        float  x  = mX(n, (int)m);
        double mn = mean[n];
        double is = invstd[n];
        float y = (float)(((double)x - mn) * is) * w + b;
        mY(n, (int)m) = y;
      }
    }
  }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dim");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();

  int64_t N = x_c.size(0);
  int64_t M = x_c.numel() / N;

  TORCH_CHECK(w_c.numel() == M, "weight numel must equal normalized_shape numel");
  TORCH_CHECK(b_c.numel() == M, "bias numel must equal normalized_shape numel");

  auto y = torch::empty_like(x_c);

  auto opts_d = x_c.options().dtype(at::kDouble);
  auto sum    = torch::zeros({N}, opts_d);
  auto sumsq  = torch::zeros({N}, opts_d);
  auto mean   = torch::empty({N}, opts_d);
  auto invstd = torch::empty({N}, opts_d);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  const int threads = 256;
  int blocksPerRow = (int)std::min<int64_t>(128, (M + threads - 1) / threads);
  if (blocksPerRow < 1) blocksPerRow = 1;

  dim3 grid1((unsigned)N, (unsigned)blocksPerRow);
  size_t smem_bytes = 2 * threads * sizeof(double);
  reduce_kernel<<<grid1, threads, smem_bytes, stream>>>(
      x_c.data_ptr<float>(), (int)N, (int)M,
      sum.data_ptr<double>(), sumsq.data_ptr<double>());

  int finthreads = 32;
  int finblocks  = (int)((N + finthreads - 1) / finthreads);
  finalize_kernel<<<finblocks, finthreads, 0, stream>>>(
      sum.data_ptr<double>(), sumsq.data_ptr<double>(),
      mean.data_ptr<double>(), invstd.data_ptr<double>(),
      (int)N, (int)M, (float)eps);

  int64_t work_units = ((M & 3) == 0) ? (M >> 2) : M;
  int normblocks = (int)std::min<int64_t>(65535, (work_units + threads - 1) / threads);
  if (normblocks < 1) normblocks = 1;
  normalize_kernel<<<normblocks, threads, 0, stream>>>(
      x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_c.data_ptr<float>(),
      mean.data_ptr<double>(), invstd.data_ptr<double>(),
      y.data_ptr<float>(), (int)N, (int)M);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single fused custom CUDA/CuTe kernel pipeline
    (partial reduction -> finalize stats -> elementwise normalize+affine).
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias.contiguous(),
            float(self.eps),
        )

